lessons.code:
p {
  color: blue;
  font-size: 18px;
}
.tit-prensipal {
  color: green;
  text-align: center;
}
#logo {
  width: 120px;
}

h1 {
  color: #1a7a3c;
  font-family: Arial, sans-serif;
  text-align: center;
}
p {
  color: #333333;
  font-size: 17px;
  line-height: 1.6;
}

* {
  box-sizing: border-box;
}
.kat {
  width: 300px;
  padding: 20px;
  border: 2px solid #1a7a3c;
  margin: 15px;
  background-color: #f5f5f5;
}

.kontene {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 15px;
  height: 100vh;
}
.atik {
  flex: 1;
  padding: 20px;
  background: #e8f5e9;
}

.galri {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
}
.tèt {
  grid-column: 1 / -1;
}

.kat {
  position: relative;
}
.badj {
  position: absolute;
  top: 10px;
  right: 10px;
  background: red;
  color: white;
}
.ba-nav {
  position: fixed;
  top: 0;
  width: 100%;
  z-index: 100;
}

.bouton {
  background: #1a7a3c;
  color: white;
  padding: 12px 24px;
  transition: background 0.3s ease, transform 0.3s ease;
}
.bouton:hover {
  background: #145c2e;
  transform: scale(1.05);
}
@keyframes flote {
  from { transform: translateY(0); }
  to { transform: translateY(-10px); }
}
.balon {
  animation: flote 2s ease-in-out infinite alternate;
}

h1 {
  font-size: clamp(1.5rem, 4vw, 3rem);
}
.kolòn {
  display: grid;
  grid-template-columns: 1fr;
}
@media (min-width: 768px) {
  .kolòn {
    grid-template-columns: 1fr 1fr;
  }
}

:root {
  --koulè-prensipal: #1a7a3c;
  --espas: 16px;
}
.bouton {
  background: var(--koulè-prensipal);
  padding: var(--espas);
  width: min(400px, 90%);
}
.tèm-nwa {
  --koulè-prensipal: #4caf50;
  background: #111;
  color: white;
}

@layer baz, konpozan, utilitè;
@layer baz {
  p { margin: 0; }
}
@layer konpozan {
  .kat p { margin: 16px; }
}
@layer utilitè {
  .san-maj { margin: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms;
    transition-duration: 0.01ms;
  }
}
bouton:focus-visible {
  outline: 3px solid #1a7a3c;
  outline-offset: 2px;
}

.kat-paran {
  container-type: inline-size;
}
@container (min-width: 400px) {
  .kat {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
}
.sou-gri {
  display: grid;
  grid-template-columns: subgrid;
}
